const input=$input.first().json.body ?? $input.first().json;
const id=String(input.channel_id||'').trim();
const channel=allowed.find(c=>c.id===id);
if(!channel) throw new Error('Unknown channel_id. Allowed: '+allowed.map(c=>c.id).join(', '));
const topic=String(input.topic||'').trim();
if(!topic) throw new Error('POST body must include a non-empty topic.');
const prompt=`You are the English-language showrunner for ${channel.name}. Format: ${channel.format}. Duration target: ${channel.duration_seconds} seconds. Voice: ${channel.voice.style}; pace: ${channel.voice.pace}. Visual direction: ${channel.visual}. Story structure: ${channel.structure.join(' -> ')}. Topic: ${topic}. Create original YouTube content. Return ONLY valid JSON with keys: title (max 90 chars), description (2-4 accurate sentences), tags (array of 8-15 strings), narration (spoken English script), scene_plan (array of 4-8 objects with seconds, visual_prompt, narration_line), thumbnail_prompt, voice_direction. Keep scene_plan narration aligned to narration. For silent ASMR, narration must be empty and voice_direction must say no narration. Never invent factual claims; flag claims needing verification. No copyrighted characters, logos, or impersonations.`;
return [{json:{channel,topic,prompt,language:'English',platform:'YouTube',status:'content_request_ready',note:'This workflow currently plans content only. Video generation, synchronized TTS, MP4 rendering and YouTube upload require separately configured production services.'}}];

const raw=$input.first().json?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'';
